        CONSTRAINT "FK_DecisionRuleEvaluationLinks_Decisions_DecisionId" FOREIGN KEY ("DecisionId") REFERENCES "Service"."Decisions" ("DecisionId") ON DELETE CASCADE,
        CONSTRAINT "FK_DecisionRuleEvaluationLinks_RuleEvaluations_RuleEvaluationId" FOREIGN KEY ("RuleEvaluationId") REFERENCES "Service"."RuleEvaluations" ("RuleEvaluationId") ON DELETE CASCADE
