DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260820181011_AddCaseDeadlinesAndEscalation') THEN
    ALTER TABLE "Service"."Cases" ADD "DueAt" timestamp with time zone NOT NULL DEFAULT TIMESTAMPTZ '-infinity';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260820181011_AddCaseDeadlinesAndEscalation') THEN
    UPDATE "Service"."Cases" AS c
    SET "DueAt" = LEAST(
        c."CreatedAt" + (targets.minutes * INTERVAL '1 minute'),
        COALESCE((
            SELECT MIN(d."ExpiresAt")
            FROM "Service"."Decisions" AS d
            WHERE d."CaseId" = c."CaseId" AND d."ExpiresAt" IS NOT NULL
        ), 'infinity'::timestamptz))
    FROM (
        VALUES (1, 10080), (2, 4320), (3, 1440), (4, 480), (5, 120)
    ) AS targets("SeverityId", minutes)
    WHERE targets."SeverityId" = c."SeverityId";
    END IF;
END $EF$;

