    CREATE TRIGGER "AuditLogs_Chain"
        BEFORE INSERT ON "Service"."AuditLogs"
        FOR EACH ROW EXECUTE FUNCTION "Service"."ChainAuditLog"();
    END IF;
END $EF$;

