DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260906115230_AddModesAndSandbox') THEN
    PERFORM setval(
        pg_get_serial_sequence('"Service"."Modes"', 'ModeId'),
        GREATEST(
            (SELECT MAX("ModeId") FROM "Service"."Modes") + 1,
            nextval(pg_get_serial_sequence('"Service"."Modes"', 'ModeId'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Service"."Permissions"', 'PermissionId'),
        GREATEST(
            (SELECT MAX("PermissionId") FROM "Service"."Permissions") + 1,
            nextval(pg_get_serial_sequence('"Service"."Permissions"', 'PermissionId'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Service"."SimulationScenarios"', 'SimulationScenarioId'),
        GREATEST(
            (SELECT MAX("SimulationScenarioId") FROM "Service"."SimulationScenarios") + 1,
            nextval(pg_get_serial_sequence('"Service"."SimulationScenarios"', 'SimulationScenarioId'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Service"."SimulationStatuses"', 'SimulationStatusId'),
        GREATEST(
            (SELECT MAX("SimulationStatusId") FROM "Service"."SimulationStatuses") + 1,
            nextval(pg_get_serial_sequence('"Service"."SimulationStatuses"', 'SimulationStatusId'))),
        false);
    END IF;
END $EF$;

