        false);
    PERFORM setval(
        pg_get_serial_sequence('"Service"."Permissions"', 'PermissionId'),
        GREATEST(
            (SELECT MAX("PermissionId") FROM "Service"."Permissions") + 1,
            nextval(pg_get_serial_sequence('"Service"."Permissions"', 'PermissionId'))),
