        pg_get_serial_sequence('"Service"."AuditableEntityTypes"', 'AuditableEntityTypeId'),
        GREATEST(
            (SELECT MAX("AuditableEntityTypeId") FROM "Service"."AuditableEntityTypes") + 1,
            nextval(pg_get_serial_sequence('"Service"."AuditableEntityTypes"', 'AuditableEntityTypeId'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Service"."Currencies"', 'CurrencyId'),
        GREATEST(
            (SELECT MAX("CurrencyId") FROM "Service"."Currencies") + 1,
            nextval(pg_get_serial_sequence('"Service"."Currencies"', 'CurrencyId'))),
        false);
