            (SELECT MAX("InvoiceLineTypeId") FROM "Service"."InvoiceLineTypes") + 1,
            nextval(pg_get_serial_sequence('"Service"."InvoiceLineTypes"', 'InvoiceLineTypeId'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Service"."InvoiceStatuses"', 'InvoiceStatusId'),
        GREATEST(
            (SELECT MAX("InvoiceStatusId") FROM "Service"."InvoiceStatuses") + 1,
            nextval(pg_get_serial_sequence('"Service"."InvoiceStatuses"', 'InvoiceStatusId'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Service"."Permissions"', 'PermissionId'),
        GREATEST(
            (SELECT MAX("PermissionId") FROM "Service"."Permissions") + 1,
            nextval(pg_get_serial_sequence('"Service"."Permissions"', 'PermissionId'))),
