DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260911185606_AddInvitations') THEN
    PERFORM setval(
        pg_get_serial_sequence('"Service"."AuditableEntityTypes"', 'AuditableEntityTypeId'),
        GREATEST(
            (SELECT MAX("AuditableEntityTypeId") FROM "Service"."AuditableEntityTypes") + 1,
            nextval(pg_get_serial_sequence('"Service"."AuditableEntityTypes"', 'AuditableEntityTypeId'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Service"."Permissions"', 'PermissionId'),
        GREATEST(
            (SELECT MAX("PermissionId") FROM "Service"."Permissions") + 1,
            nextval(pg_get_serial_sequence('"Service"."Permissions"', 'PermissionId'))),
        false);
    END IF;
END $EF$;

