        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_ServiceCostRates" PRIMARY KEY ("ServiceCostRateId"),
        CONSTRAINT "FK_ServiceCostRates_BillableResources_BillableResourceId" FOREIGN KEY ("BillableResourceId") REFERENCES "Service"."BillableResources" ("BillableResourceId") ON DELETE RESTRICT,
        CONSTRAINT "FK_ServiceCostRates_Currencies_CurrencyId" FOREIGN KEY ("CurrencyId") REFERENCES "Service"."Currencies" ("CurrencyId") ON DELETE RESTRICT,
